import React, { useState } from 'react'
import { supabase } from '../lib/supabase'

export default function CommentSection({ postId, comments, onRefresh, currentUser }) {
    const [newComment, setNewComment] = useState('')
    const [replyingTo, setReplyingTo] = useState(null)
    const [replyText, setReplyText] = useState('')
    const [submitting, setSubmitting] = useState(false)

    const handleComment = async (e) => {
        e.preventDefault()
        if (!newComment.trim() || !currentUser) return

        setSubmitting(true)
        try {
            const { data, error } = await supabase
                .from('post_comments')
                .insert({
                    post_id: postId,
                    user_id: currentUser.id,
                    text: newComment.trim()
                })
                .select()
                .single()

            if (error) throw error

            // Update comment count on post
            await supabase
                .from('posts')
                .update({ comments_count: (comments?.length || 0) + 1 })
                .eq('id', postId)

            setNewComment('')
            if (onRefresh) onRefresh()
        } catch (error) {
            console.error('Error commenting:', error)
            alert('Failed to add comment')
        } finally {
            setSubmitting(false)
        }
    }

    const handleReply = async (commentId) => {
        if (!replyText.trim() || !currentUser) return

        setSubmitting(true)
        try {
            const { data, error } = await supabase
                .from('comment_replies')
                .insert({
                    comment_id: commentId,
                    user_id: currentUser.id,
                    text: replyText.trim()
                })
                .select()
                .single()

            if (error) throw error

            setReplyText('')
            setReplyingTo(null)
            if (onRefresh) onRefresh()
        } catch (error) {
            console.error('Error replying:', error)
            alert('Failed to add reply')
        } finally {
            setSubmitting(false)
        }
    }

    return (
        <div>
            {/* Existing Comments */}
            {comments?.map((comment) => (
                <div key={comment.id} className="mb-3">
                    <div className="flex gap-2">
                        <div className="w-8 h-8 bg-gray-300 rounded-full flex items-center justify-center text-xs font-bold">
                            {comment.profiles?.username?.[0]?.toUpperCase() || 'U'}
                        </div>
                        <div className="flex-1">
                            <div className="bg-gray-100 rounded-lg px-3 py-2">
                                <span className="font-semibold text-sm">
                                    {comment.profiles?.full_name || comment.profiles?.username || 'Unknown'}
                                </span>
                                <p className="text-sm text-gray-800">{comment.text}</p>
                            </div>
                            <div className="flex gap-4 mt-1 text-xs text-gray-500">
                                <button 
                                    onClick={() => setReplyingTo(replyingTo === comment.id ? null : comment.id)}
                                    className="hover:text-green-600 transition"
                                >
                                    Reply
                                </button>
                                <span>{new Date(comment.created_at).toLocaleDateString()}</span>
                            </div>

                            {/* Replies */}
                            {comment.replies?.map((reply) => (
                                <div key={reply.id} className="flex gap-2 mt-2 ml-8">
                                    <div className="w-6 h-6 bg-gray-300 rounded-full flex items-center justify-center text-[10px] font-bold">
                                        {reply.profiles?.username?.[0]?.toUpperCase() || 'U'}
                                    </div>
                                    <div className="flex-1">
                                        <div className="bg-gray-50 rounded-lg px-3 py-1.5">
                                            <span className="font-semibold text-xs">
                                                {reply.profiles?.full_name || reply.profiles?.username || 'Unknown'}
                                            </span>
                                            <p className="text-sm text-gray-700">{reply.text}</p>
                                        </div>
                                    </div>
                                </div>
                            ))}

                            {/* Reply Input */}
                            {replyingTo === comment.id && (
                                <div className="flex gap-2 mt-2 ml-8">
                                    <input
                                        type="text"
                                        value={replyText}
                                        onChange={(e) => setReplyText(e.target.value)}
                                        placeholder="Write a reply..."
                                        className="flex-1 px-3 py-1.5 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-green-500"
                                    />
                                    <button
                                        onClick={() => handleReply(comment.id)}
                                        disabled={submitting || !replyText.trim()}
                                        className="px-3 py-1.5 bg-green-600 text-white rounded-lg text-sm hover:bg-green-700 disabled:opacity-50"
                                    >
                                        Reply
                                    </button>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            ))}

            {/* Add Comment */}
            <form onSubmit={handleComment} className="flex gap-2 mt-2">
                <input
                    type="text"
                    value={newComment}
                    onChange={(e) => setNewComment(e.target.value)}
                    placeholder="Write a comment..."
                    className="flex-1 px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-green-500"
                />
                <button
                    type="submit"
                    disabled={submitting || !newComment.trim()}
                    className="px-4 py-2 bg-green-600 text-white rounded-lg text-sm font-semibold hover:bg-green-700 disabled:opacity-50"
                >
                    Post
                </button>
            </form>
        </div>
    )
}
